<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>RideFixer Shop - E-Bike Parts Coming Soon</title>
  <meta name="description" content="RideFixer Shop is launching soon with e-bike parts, displays, controllers, batteries, motors and repair-first replacement guidance." />
  <link rel="canonical" href="https://shop.ridefixer.app/" />
  <meta name="theme-color" content="#06101d" />
  <link rel="icon" href="/my-android-app/android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png" />
  <link rel="apple-touch-icon" href="/my-android-app/android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png" />
  <style>
    :root{--bg:#06101d;--bg2:#081827;--card:rgba(255,255,255,.08);--card2:rgba(255,255,255,.12);--text:#f8fbff;--muted:#a9b8ca;--line:rgba(255,255,255,.14);--brand:#00d4ff;--green:#22c7a9;--shadow:0 24px 70px rgba(0,0,0,.35)}
    html[data-theme='light']{--bg:#f7fbff;--bg2:#edf4fa;--card:rgba(255,255,255,.95);--card2:#ffffff;--text:#0b1724;--muted:#5f7186;--line:rgba(8,24,39,.10);--shadow:0 18px 45px rgba(8,24,39,.08)}
    *{box-sizing:border-box} html,body{margin:0;padding:0} body{font-family:Inter,Manrope,system-ui,sans-serif;color:var(--text);min-height:100vh;background:radial-gradient(circle at 10% 0%,rgba(0,212,255,.18),transparent 28%),radial-gradient(circle at 90% 10%,rgba(34,199,169,.14),transparent 28%),linear-gradient(180deg,var(--bg),var(--bg2) 48%,var(--bg));overflow-x:hidden;transition:.25s ease}.wrap{width:min(1120px,92vw);margin:0 auto}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:12px;font-weight:900;font-size:1.22rem;color:inherit;text-decoration:none}.brand img{width:44px;height:44px;border-radius:14px;box-shadow:0 18px 48px rgba(0,212,255,.25)}.nav a{color:var(--muted);text-decoration:none;font-weight:750}.pill{padding:10px 15px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.07);color:var(--text);cursor:pointer}.hero{padding:46px 0 22px;display:grid;grid-template-columns:1.1fr .9fr;gap:18px}.card{background:linear-gradient(145deg,var(--card2),var(--card));border:1px solid var(--line);border-radius:30px;box-shadow:var(--shadow);padding:30px}.eyebrow{display:inline-flex;padding:8px 12px;border-radius:999px;border:1px solid rgba(0,212,255,.28);background:rgba(0,212,255,.10);color:#0fd6ff;font-size:.82rem;font-weight:850}h1,h2,h3{margin:0;letter-spacing:-.6px}h1{font-size:clamp(2.4rem,6vw,5rem);line-height:.95;margin-top:16px}.gradient{background:linear-gradient(135deg,var(--brand),#fff,var(--green));-webkit-background-clip:text;-webkit-text-fill-color:transparent}.sub{color:var(--muted);line-height:1.7}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}.btn{display:inline-flex;align-items:center;justify-content:center;padding:13px 18px;border-radius:999px;font-weight:900;text-decoration:none}.btn-primary{background:linear-gradient(135deg,var(--brand),var(--green));color:#00131a}.btn-ghost{border:1px solid var(--line);background:rgba(255,255,255,.08);color:var(--text)}.visual{display:grid;place-items:center;text-align:center;min-height:360px}.bike{font-size:7rem}.section{margin-top:18px}.grid,.mini{display:grid;gap:14px;margin-top:16px}.grid{grid-template-columns:repeat(3,1fr)}.mini{grid-template-columns:repeat(3,1fr)}.item,.mini div{padding:20px;border-radius:24px;background:rgba(255,255,255,.07);border:1px solid var(--line)}.icon{font-size:2rem;margin-bottom:10px}.notice{text-align:center;background:linear-gradient(135deg,rgba(34,199,169,.12),rgba(0,212,255,.08))}.footer{padding:30px 0 42px;color:var(--muted);display:flex;justify-content:space-between;flex-wrap:wrap}.footer a{color:inherit}@media(max-width:860px){.hero,.grid,.mini{grid-template-columns:1fr}.nav{height:auto;padding:14px 0;flex-wrap:wrap}.card{padding:22px}.actions .btn{width:100%}}
  </style>
</head>
<body>
<nav class="wrap nav">
  <a class="brand" href="https://shop.ridefixer.app/"><img src="/my-android-app/android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png" alt="RideFixer" /><span>RideFixer Shop</span></a>
  <div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;">
    <a href="#categories">Categories</a>
    <a href="#request">Request Part</a>
    <a class="pill" href="https://ridefixer.app/">Diagnostics</a>
    <button id="themeToggle" class="pill" type="button">🌙</button>
  </div>
</nav>
<main class="wrap">
<section class="hero">
<article class="card"><span class="eyebrow">E-Bike Parts Marketplace • Launching Soon</span><h1>Repair-first <span class="gradient">e-bike parts</span> for real riders.</h1><p class="sub">RideFixer Shop is being built as a focused marketplace for displays, controllers, batteries, motors and repair-first replacement parts.</p><div class="actions"><a class="btn btn-primary" href="mailto:ridefixer232@gmail.com">Request a Part</a><a class="btn btn-ghost" href="https://ridefixer.app/error-codes">Diagnose First</a></div></article>
<aside class="card visual"><div><div class="bike">🛒</div><h2>Store v1 is coming</h2><p class="sub">Built around diagnostics and compatibility workflows.</p></div></aside>
</section>
<section id="categories" class="card section"><h2>Planned Categories</h2><div class="grid"><div class="item"><div class="icon">🔋</div>Batteries</div><div class="item"><div class="icon">🖥️</div>Displays</div><div class="item"><div class="icon">⚙️</div>Controllers</div><div class="item"><div class="icon">🎛️</div>Throttles</div><div class="item"><div class="icon">🛞</div>Motors & Wheels</div><div class="item"><div class="icon">🛠️</div>Repair Essentials</div></div></section>
<section id="request" class="card section notice"><h2>Need an e-bike part?</h2><p class="sub">Send us the display model, error code or part name and we’ll prioritise real demand first.</p><div class="actions" style="justify-content:center"><a class="btn btn-primary" href="mailto:ridefixer232@gmail.com">Request by Email</a></div></section>
<section class="card section"><h2>Compatibility focus</h2><div class="mini"><div><strong>SW900</strong></div><div><strong>S866</strong></div><div><strong>KT LCD</strong></div></div></section>
</main>
<footer class="wrap footer"><span>© 2026 RideFixer Shop</span><span><a href="https://ridefixer.app/">RideFixer Diagnostics</a></span></footer>
<script>(function(){const root=document.documentElement;const saved=localStorage.getItem('ridefixer-shop-theme');const prefers=window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';root.setAttribute('data-theme',saved||prefers);const btn=document.getElementById('themeToggle');const sync=()=>btn.textContent=root.getAttribute('data-theme')==='dark'?'☀️':'🌙';btn.addEventListener('click',()=>{const next=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',next);localStorage.setItem('ridefixer-shop-theme',next);sync();});sync();})();</script>
</body>
</html>